import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import test from 'node:test';import assert from 'node:assert/strict';import {randomUUID,createCipheriv,createDecipheriv,randomBytes} from 'node:crypto';import {createRequire} from 'node:module';
