const seal=async bytes=>{const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',master,iv),data=Buffer.concat([cipher.update(bytes),cipher.final()]);return Buffer.concat([iv,cipher.getAuthTag(),data]);};
const unseal=async bytes=>{const cipher=createDecipheriv('aes-256-gcm',master,bytes.subarray(0,12));cipher.setAuthTag(bytes.subarray(12,28));return Buffer.concat([cipher.update(bytes.subarray(28)),cipher.final()]);};
