test('Known managed remote ID waits for private vault readiness and resumes only GET to the same recorded task',async()=>{const model=registry.modelDescriptors().find(model=>model.providerId==='own-video'),created=await registry.createGenerationTask(model.id,{studioModelId:model.id,prompt:'OWNED_HOLD_RESTART'},'workspace-restart');let remote;for(let n=0;n<100;n++){remote=[...peer.tasks.values()].find(task=>task.input.prompt==='OWNED_HOLD_RESTART');if(remote&&peer.requests.some(row=>row.method==='GET'&&row.taskId===remote.id))break;await new Promise(resolve=>setTimeout(resolve,10));}assert.ok(remote);const count=()=>peer.requests.filter(row=>row.method==='GET'&&row.taskId===remote.id).length;const before=count();await registry.close();await asset.close();open({unseal:async bytes=>{await new Promise(resolve=>setTimeout(resolve,60));return unseal(bytes);}});await new Promise(resolve=>setTimeout(resolve,20));assert.equal(count(),before);await registry.ready;for(let n=0;n<100&&count()===before;n++)await new Promise(resolve=>setTimeout(resolve,10));assert.ok(count()>before);remote.plan.pendingPolls=0;assert.equal((await done(created.task.id)).status,'completed');assert.equal(peer.requests.filter(row=>row.method==='POST'&&row.body.prompt==='OWNED_HOLD_RESTART').length,1);});
