test('Updating an existing key rolls back vault pointer, metadata and private cache on failed registry commit',async()=>{const file=path.join(root,'registry','registry.json'),linked=path.join(root,'registry-update-linked.json'),before=fs.readFileSync(file),stored=JSON.parse(before).providers['own-model'],ref=stored._credentialRef,oldVault=fs.readFileSync(path.join(root,'registry',ref)),oldFiles=fs.readdirSync(path.join(root,'registry')).filter(name=>name.endsWith('.vault')).sort();fs.linkSync(file,linked);try{await assert.rejects(()=>registry.dispatch('save',{provider:{id:'own-model',apiKey:'owned-rotated-key-'+randomUUID()}}),/Linked/);assert.deepEqual(fs.readFileSync(linked),before);assert.deepEqual(fs.readFileSync(path.join(root,'registry',ref)),oldVault);assert.deepEqual(fs.readdirSync(path.join(root,'registry')).filter(name=>name.endsWith('.vault')).sort(),oldFiles);assert.equal((await registry.dispatch('list')).providers.find(provider=>provider.id==='own-model').apiKeyConfigured,true);const model=registry.modelDescriptors().find(model=>model.providerId==='own-model');const created=await registry.createGenerationTask(model.id,{studioModelId:model.id,prompt:'OWNED_AFTER_FAILED_ROTATION'},'workspace-old-key');assert.equal((await done(created.task.id)).status,'completed');assert.equal(peer.requests.find(row=>row.body.prompt==='OWNED_AFTER_FAILED_ROTATION').authorized,true);}finally{fs.unlinkSync(linked);}});
