test('Meaningful scene sends independent prompt resolution/ratio requirements with unknown API capabilities, preserves braces and durable original history',async()=>{await registry.dispatch('save',{provider:{...configuration,id:'own-prompt-hints'}});await registry.dispatch('syncModels',{providerId:'own-prompt-hints'});const model=registry.modelDescriptors().find(model=>model.providerId==='own-prompt-hints');assert.equal(model.capabilities.size.status,'unknown');const original='A warmly lit game-development studio overlooking a rainy city: a wooden desk, sketchbooks, a brass task lamp and a small plant. Preserve the literal studio sign {{model}}.';const expected=original+'\n\n[Image output requirements]\nRequired final image resolution: 2048 x 1152 pixels.\nRequired final image aspect ratio: 16:9.\nCompose the whole scene for these output requirements.';const created=await registry.createImageTask(model.id,{studioModelId:model.id,model:model.model,prompt:original,resolutionHint:'2048x1152',aspectRatioHint:'16:9'},'workspace-scene');const task=await done(created.task.id);assert.equal(task.status,'completed');assert.equal(task.prompt,original);assert.equal(task.parameters.prompt,original);assert.equal(task.parameters.resolutionHint,'2048x1152');assert.equal(task.parameters.aspectRatioHint,'16:9');assert.equal(task.executionPrompt,expected);assert.deepEqual(peer.requests.at(-1).body,{model:model.model,prompt:expected,n:1});assert.ok(peer.requests.at(-1).body.prompt.includes('{{model}}'));const stored=JSON.parse(fs.readFileSync(path.join(root,'assets','tasks.json')))[task.id];assert.equal(stored._managedRequestPrompt,expected);assert.equal(typeof stored._managedOriginalPromptSha256,'string');assert.equal(stored._managedOriginalPromptSha256.length,64);assert.equal(stored._managedRequestPromptSha256.length,64);const before=peer.requests.length;await registry.close();await asset.close();open();await registry.ready;await new Promise(resolve=>setTimeout(resolve,30));const resumed=(await asset.dispatch('generator/getTask',{taskId:task.id})).task;assert.equal(resumed.prompt,original);assert.equal(resumed.executionPrompt,expected);assert.equal(peer.requests.length,before);});
