test('Explicit OpenAI size policy sends actual API pixels without granting unknown quality, preserves prompt and decodes the real smaller artifact',async()=>{await registry.dispatch('save',{provider:{...configuration,id:'own-openai-size',imageSizePolicy:'openai-size'}});await registry.dispatch('syncModels',{providerId:'own-openai-size'});const model=registry.modelDescriptors().find(model=>model.providerId==='own-openai-size'),original='A hand-painted fantasy harbor at sunset, with timber docks, colorful market awnings and a windmill on the hill; preserve {{model}} lettering.';assert.equal(model.imageSizePolicy,'openai-size');assert.equal(model.imageSizePolicyInfo.evidence,'manual');assert.equal(model.capabilities.size.status,'unknown');assert.equal(model.capabilities.quality.status,'unknown');const made=await registry.createImageTask(model.id,{studioModelId:model.id,prompt:original,resolutionHint:'3840x2160',aspectRatioHint:'16:9'},'workspace-size'),task=await done(made.task.id),request=peer.requests.at(-1);assert.equal(task.status,'completed');assert.equal(task.prompt,original);assert.equal(task.parameters.prompt,original);assert.equal(task.parameters.size,'3840x2160');assert.deepEqual(request.body,{model:model.model,prompt:task.executionPrompt,n:1,size:'3840x2160'});assert.ok(request.body.prompt.includes('{{model}}'));assert.match(request.body.prompt,/3840 x 2160 pixels/);assert.equal(task.artifacts[0].width,48);assert.equal(task.artifacts[0].height,32);assert.equal(task.artifacts[0].sha256,peer.media.png.sha256);assert.equal(registry.resolveModel(model.id).capabilities.size.status,'unknown');const fromApi=await registry.createImageTask(model.id,{studioModelId:model.id,prompt:original,size:'2880x2880'},'workspace-size');assert.equal((await done(fromApi.task.id)).parameters.size,'2880x2880');assert.equal(peer.requests.at(-1).body.size,'2880x2880');const nominal=await registry.createImageTask(model.id,{studioModelId:model.id,prompt:original,resolutionHint:'3520x2336',aspectRatioHint:'3:2'},'workspace-size');assert.equal((await done(nominal.task.id)).status,'completed');assert.equal(peer.requests.at(-1).body.size,'3520x2336');assert.match(peer.requests.at(-1).body.prompt,/aspect ratio: 3:2/);const defaultRequest=await registry.createImageTask(model.id,{studioModelId:model.id,prompt:original,resolutionHint:'auto'},'workspace-size');await done(defaultRequest.task.id);assert.deepEqual(peer.requests.at(-1).body,{model:model.model,prompt:original,n:1});});
