  const history=await compatibility.dispatch({method:'GET',path:'/task/'+task.id+'/status',origin:peer.baseUrl,workspaceKey:'workspace-video-fields'});assert.equal(history.status,200);assert.equal(history.body.category,'video');assert.deepEqual(history.body.input.data.parameters,parameters);assert.equal(history.body.input.data.prompt,original);assert.equal(history.body.output.data.artifacts[0].sha256,peer.media.mp4.sha256);assert.equal(history.body.output.data.artifacts[0].width,32);assert.equal(history.body.output.data.artifacts[0].dimensionKind,'display');assert.equal(history.body.output.data.artifacts[0].dimensionsSource,'mp4-video-track-header');
