test('Declared URL image transport preserves gateway inline image bytes as verified owned artifacts and rejects bad data URIs',async()=>{
  const calls=[],runtime=createAssetService({root:path.join(root,'inline-url-runtime'),pollIntervalMs:10,requestTimeoutMs:1000,fetch:async(url,init)=>{assert.equal(init.method,'POST');calls.push({url:String(url),body:JSON.parse(init.body)});return new Response(JSON.stringify({data:[{url:activeUri}]}));}});
  const local=createProviderRegistry({root:path.join(root,'inline-url-registry'),assetService:runtime,fetch:async(_url,init)=>{assert.equal(init.method,'GET');return new Response(JSON.stringify({data:[{id:'owned-inline-model'}]}));},seal,unseal});
  let activeUri='data:image/png;base64,'+peer.media.png.bytes.toString('base64');
  const wait=async id=>{for(let n=0;n<200;n++){const {task}=await runtime.dispatch('generator/getTask',{taskId:id});if(['completed','failed','interrupted'].includes(task.status))return task;await new Promise(resolve=>setTimeout(resolve,5));}throw Error('Owned inline image deadline');};
  try {
    await local.dispatch('save',{provider:{id:'own-inline-url',name:'Own URL transport',protocol:'openai-images',baseUrl:'http://127.0.0.1:9183',kinds:['image'],authMode:'none'}});await local.dispatch('syncModels',{providerId:'own-inline-url'});const model=local.modelDescriptors()[0];await local.recordModelCapabilities({providerId:model.providerId,modelId:model.model,capabilities:{outputFormat:{status:'supported',evidence:'manual',choices:['url','b64_json'],requestField:'response_format'}}});
    const create=()=>local.createImageTask(model.id,{studioModelId:model.id,prompt:'Owned URL output transport',outputFormat:'url'},'workspace-inline'),initial=await create(),task=await wait(initial.task.id);assert.equal(task.status,'completed');assert.equal(task.artifacts[0].sha256,peer.media.png.sha256);assert.equal(task.artifacts[0].width,48);assert.equal(task.artifacts[0].height,32);assert.equal(calls.length,1);assert.equal(calls[0].body.response_format,'url');assert.equal(calls[0].body.output_format,undefined);assert.equal(runtime.getArtifactPath(task.id,task.artifacts[0].id).sha256,peer.media.png.sha256);assert.equal(JSON.stringify(task).includes('data:image/'),false);
    for(const bad of ['data:text/html;base64,PGgxPm5vPC9oMT4=','data:image/png;base64,not-base64!','data:image/png;base64,AAAA','data:image/jpeg;base64,'+peer.media.png.bytes.toString('base64')]){activeUri=bad;const failed=await wait((await create()).task.id);assert.equal(failed.status,'failed');assert.equal(failed.artifacts.length,0);}
    assert.equal(calls.length,5,'Inline URL decoding never creates external GET or a second POST');
  }finally{await local.close();await runtime.close();}
});
